import{_ as t,c as n,b as a,o}from"./app-DRXmfGxI.js";const r={};function p(i,e){return o(),n("div",null,e[0]||(e[0]=[a('<p><a href="https://webkul.com/blog/shopify-multivendor-marketplace-new-theme-launched/" target="_blank" rel="noopener noreferrer">Multivendor Marketplace app for Shopify</a> -Canada Post feature helps the sellers of Canada to ship their products worldwide</p><p>And sellers can also generate &quot;shipping label&quot; from their account on Multivendor Marketplace App.</p><p><strong>Important Note</strong>:- “This Shipping Feature is available only in the Multivendor <strong>PRO ($60/month)</strong> Plan <strong>+</strong> You need to enable the “Shipping” Feature App which is <strong>FREE</strong> of cost.”</p><p>This feature will have additional charges of USD 10 per month over and above your current multivendor plan.</p><p>Moreover, please Note:- <br> To make this shipping feature work, you need to choose the Shopify store plan which supports the <strong>“Real-Time Carrier-Calculated Shipping”.</strong></p><p>So let&#39;s understand its workflow:-</p><h3 id="admin-end" tabindex="-1"><a class="header-anchor" href="#admin-end"><span>ADMIN END</span></a></h3><p>Firstly enable the feature from the &quot;FEATURE APPS&quot; section on the top right-hand side of the main menu in your Marketplace App.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/Screenshot-26.png" alt="Multi Vendor Marketplace Canada Post"></p><p>Once you will click on the Enable button, the Plan amount window will open and USD 10 will be added to your current payment.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/g.png" alt="Multi Vendor Marketplace Canada Post"></p><p>Now you also have to enable this feature from the &quot;shipping configuration&quot; section of your Multivendor Marketplace app.</p><p><strong>Note</strong>: Kindly choose only those shipping services which you need. Don&#39;t keep all the services selected otherwise it creates delay to retrieve shipping rates at the storefront.</p><p>Configuration&gt;&gt;Shipping Configuration&gt;&gt; Select &quot;Canada Post&quot;&gt;&gt; Save changes</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/Screenshot-22.png" alt="Multi Vendor Marketplace Canada Post"></p><p>Hence a new menu name &quot;Canada Post Configuration&quot; will be added in the configuration section of your admin panel in your multivendor marketplace app</p><p>And here you need to configure the feature by entering the details of Canada post username, Canada post password, Canada post customer number.</p><p>Configuration&gt;&gt; Canada Post Configuration&gt;&gt; Enter Canada post username|password|customer number&gt;&gt;save</p><p>Further, you can allow your sellers to generate the shipping label automatically for the fulfilled orders.</p><p>You can also choose whether you want the <strong>admin</strong> or the <strong>seller</strong> to bear the extra Shipping charges (Shipping Label cost).</p><p>Once you select “Admin” to bear the Shipping Label cost, the same process will be applied(admin will pay the shipping label cost).</p><p>But if you want your sellers to bear the extra Shipping charges then the seller will pay the shipping label cost as per the shipping configured by the admin.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/01101036/screencapture-sp-seller-webkul-admin-index-php-2019-07-01-15-32-23-1.png" alt="Multi Vendor Marketplace Canada Post"></p><p>If the Admin wants his sellers to enter their own Shipping details then he can enable the &#39;Seller Canada Post Detail&#39; option.</p><p>This option will introduce a &#39;Canada Post Configuration&#39; sub-menu on the Seller&#39;s end.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/01104253/screencapture-sp-seller-webkul-admin-index-php-2019-07-01-16-09-50.png" alt="Multi Vendor Marketplace Canada Post"></p><p>In this way, you can configure your shipping details.</p><h3 id="add-shipping-method-to-product" tabindex="-1"><a class="header-anchor" href="#add-shipping-method-to-product"><span>Add Shipping Method to Product</span></a></h3><p>Once you configure the Canada post shipping details, you will have the option to choose a shipping method for each product while adding/editing a product.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/12/Screenshot2-1-1200x619.png" alt="Multi Vendor Marketplace Canada Post"></p><h2 id="make-shipping-address-phone-number-mandatory" tabindex="-1"><a class="header-anchor" href="#make-shipping-address-phone-number-mandatory"><span>Make <strong>Shipping</strong> <strong>Address Phone Number</strong> Mandatory</span></a></h2><p>To use this feature add-on, the admin needs to make the <strong>Shipping</strong> <strong>address phone number mandatory</strong> at the time of <strong>checkout</strong>.</p><p>So, to do this, go to <strong>Shopify Backend</strong> &gt; <strong>Settings</strong> &gt; <strong>Checkout</strong> &gt; Under <strong>Form Options</strong>, make <strong>Shipping</strong> <strong>address phone number</strong> as <strong>Required</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/demo-store-Checkout-Shopify-1200x597.png" alt="133"></p><h3 id="seller-end" tabindex="-1"><a class="header-anchor" href="#seller-end"><span>SELLER END</span></a></h3><p>Further, on the seller end, Seller needs to select the &quot;Canada Post&quot; shipping feature from the &quot;Shipping configuration&quot; section from their account in the Multivendor Marketplace App.</p><p>Seller End&gt;&gt;Configuration&gt;&gt; Shipping Configuration&gt;&gt; select Canada Post&gt;&gt; Save Changes</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/Screenshot-23.png" alt="Multi Vendor Marketplace Canada Post"></p><p>After selecting the Canada Post method, the Seller needs to configure the Canada Post Details if configured by the admin.</p><p>Go to Seller End&gt;&gt;Configuration&gt;&gt; <strong>Canada Post Configuration</strong> and configure the details.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/01104848/screencapture-sp-seller-webkul-index-php-2019-07-01-16_17_58.png" alt="Multi Vendor Marketplace Canada Post"></p><p>Now, as soon as your buyer proceeds for checkout, he will get the shipping methods on the checkout page.</p><p>There will be two cases:</p><p><strong>Case 1:</strong> A seller from Canada is shipping to a Canadian Address<br> In this case, domestic shipping is applied.</p><p><strong>Case 2:</strong> A seller from Canada is shipping to an address outside Canada.</p><p>This is the case when international shipping is applied and buyers will get international shipping options to choose. Example: International Parcel Surface, International Parcel Air, etc.</p><p>Therefore, they can choose any of the shipping methods and can proceed to checkout.</p><h3 id="create-pickup-request" tabindex="-1"><a class="header-anchor" href="#create-pickup-request"><span>CREATE PICKUP REQUEST</span></a></h3><p>Your sellers can now create pickup requests for the Canada post shipping service providers.</p><p>The provider will come to pick up the orders from the specified seller location and deliver it to the customers.</p><p>Once an order is fulfilled, the seller can create a pickup request from the Action menu of the additional detail section of the Order detail page.</p><p><strong>Steps to create a pickup request:</strong></p><ul><li>Click the &quot;Create Pickup Request&quot; button in the Action menu.</li><li>Check Pickup availability by entering the postal code.</li><li>If available, select a pick-up date.</li><li>Based on the selected date, the total pick up price will be shown.</li><li>Now, select a Pickup time, enter packet volume &amp; pick up instruction.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/Screenshot-25-1.png" alt="Multi Vendor Marketplace Canada Post"></p><p>Clicking the Create Pickup Request button:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/Order-Details-Seller-•-Multivendor-MarketPlace-1.png" alt="Multi Vendor Marketplace Canada Post"></p><p>This way, you can create pick up requests using the Canada Post shipping feature app.</p><p><strong>NOTE</strong>:- Once the order is delivered via the Canada Post shipping method,</p><p>the status gets auto-updated on the Seller panel of the multi-vendor app via auto-delivery status feature.</p><h3 id="order-tracking" tabindex="-1"><a class="header-anchor" href="#order-tracking"><span>Order Tracking</span></a></h3><p>The Seller, as well as the Admin, can track the order from the Fulfillment Details section of the Order Details Page.</p><p>Multi Vendor Marketplace Admin/Seller Panel &gt; Orders &gt; Order Listing &gt; View (Action) &gt; Fulfillment Details Section (refer the image given below):</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/07/05062657/screenshot6.png" alt="Multi Vendor Marketplace Canada Post"></p><h3 id="shipping-label" tabindex="-1"><a class="header-anchor" href="#shipping-label"><span>SHIPPING Label</span></a></h3><p>The seller can also generate the shipping label from the orders section of their account in the Multivendor marketplace app.</p><p>Seller end &gt;&gt;orders&gt;&gt;order listing&gt;&gt;click on view button in the “Action” section on the front of order ID&gt;&gt; Generate Shipping Label.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/k-3.png" alt="Multi Vendor Marketplace Canada Post"></p><h3 id="demo" tabindex="-1"><a class="header-anchor" href="#demo"><span>DEMO</span></a></h3><p><strong><a href="https://multivendor-marketplace-5.myshopify.com/pages/seller-profile" target="_blank" rel="noopener noreferrer">https://multivendor-marketplace-5.myshopify.com/</a></strong></p>',69)]))}const l=t(r,[["render",p]]),d=JSON.parse('{"path":"/zenith/Featured-App/Shipping/CANADA%20POST%20SHIPPING.html","title":"CANADA POST SHIPPING","lang":"en-US","frontmatter":{"title":"CANADA POST SHIPPING","description":"CANADA POST SHIPPING","date":"2025-07-18T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"ADMIN END","slug":"admin-end","link":"#admin-end","children":[]},{"level":3,"title":"Add Shipping Method to Product","slug":"add-shipping-method-to-product","link":"#add-shipping-method-to-product","children":[]},{"level":2,"title":"Make Shipping Address Phone Number Mandatory","slug":"make-shipping-address-phone-number-mandatory","link":"#make-shipping-address-phone-number-mandatory","children":[{"level":3,"title":"SELLER END","slug":"seller-end","link":"#seller-end","children":[]},{"level":3,"title":"CREATE PICKUP REQUEST","slug":"create-pickup-request","link":"#create-pickup-request","children":[]},{"level":3,"title":"Order Tracking","slug":"order-tracking","link":"#order-tracking","children":[]},{"level":3,"title":"SHIPPING Label","slug":"shipping-label","link":"#shipping-label","children":[]},{"level":3,"title":"DEMO","slug":"demo","link":"#demo","children":[]}]}],"git":{},"filePathRelative":"zenith/Featured-App/Shipping/CANADA POST SHIPPING.md"}');export{l as comp,d as data};
